"""
    Aggregate state total financial outlay for FRT

    Arguments:
        results {dict} -- Result set from `get_state_frts`
    Returns:
        float -- Returns total financial outlay
    """
def _sum_state_financial_outlay(results: dict) -> object {
    if (results == None) {
        return 0;
    }
    total_financial_outlay = 0;
    for result in results {
        if result['financial_outlay_cr'] {
            total_financial_outlay += result['financial_outlay_cr'];
        }
    }
    return total_financial_outlay;
}

""" Scale the potential by scaling factor

        :param pot: potential along a coordinate
        :type pot: dict[tuple(float)] = float
        :param scale_coeff: initial scaling coeffcient
        :type scael_coeff: float
        :param num_tors: number of torsions used in scaling
        :type num_tors: int
        :rtype:
    """
def scale(pot: Any, scale_factor: Any) -> object {
    new_pot = {};
    for (idx, val) in pot.items() {
        new_pot[idx] = val * scale_factor;
    }
    return new_pot;
}

