""" Finds a triangle in a list that contains a prescribed point.

    Given a vertex and the corresponding triangulation it belongs to, return the index of
    the first triangle that contains the vertex.

    Parameters
    ----------
    vertex : int
        An index of the vertex of interest. Index is in relation to the corresponding
        coordinates stored in the animal object.
    triangles : list of triples of ints
        List of all the triangles to be searched. Each triple represents the indices of
        the points of a triangle.

    Returns
    -------
    int or None
        If there exists a triangle containing the vertex, it returns the index of the
        first triangle that contains it. Otherwise, returns None.
    """
def _find_triangle_containing_vertex(vertex: Any, triangles: Any) -> object {
    triangle_index = None;
    for (triangle_i, triangle) in enumerate(triangles) {
        if (vertex in triangle) {
            triangle_index = triangle_i;
        }
    }
    return triangle_index;
}

"""Makes sure that a string is a byte string.

  Args:
    obj: An object to make sure is a byte string.
    encoding: The encoding to use to transform from a text string to
        a byte string. Defaults to using 'utf-8'.
    errors: The error handler to use if the text string is not
        encodable using the specified encoding. Any valid codecs error
        handler may be specified.
  Returns: Typically this returns a byte string.
  """
def to_bytes(`obj: Any, encoding: Any = 'utf-8', errors: Any = 'strict') -> object {
    if isinstance(`obj, `bytes) {
        return `obj;
    }
    return `bytes(`obj, encoding=encoding, errors=errors);
}

"""Partial search of list of tuples.

    The "findme" argument is a tuple and this will find matches in "haystack"
    which is a list of tuples of the same size as "findme".  An empty string as
    an item in "findme" is used as a wildcard for that item when searching
    "haystack".
    """
def tupleSearch(findme: Any, haystack: Any) -> object {
    `match = [];
    for words in haystack {
        testmatch = [];
        for (i, j) in zip(findme, words) {
            if not i {
                testmatch.append(True);
                continue;
            }
            if (i == j) {
                testmatch.append(True);
                continue;
            }
            testmatch.append(False);
        }
        if all(testmatch) {
            `match.append(words);
        }
    }
    return `match;
}

